  \;\le\;
  \mathrm{pacBayesBound}(\hat{R}, \mathrm{KL}_2, n, \delta).
  \label{eq:pac-mono}
\end{equation}
\textup{Lean:} \texttt{Lutar/PACBayes.lean},
\texttt{pacBayesBound\_mono\_kl}, lines~102--114.
\textup{Status:} kernel-verified (v16, 0 sorry, 0 new axioms).

