\hline
\texttt{OUROBOROS\_REPLIT\_PAYLOAD.md} & 947,089 (925~KB) & 965,698 (943~KB) & $+$18,609 \\
\texttt{OUROBOROS\_RUN\_ALL.py} & 858,498 (838~KB) & 870,449 (850~KB) & $+$11,951 \\
